function parseMoneyBRL(text) {
  if (!text) return 0;
  // CRÍTICO: Remover caracteres Unicode bidirecionais
  let cleaned = text
    .replace(/[\u2066\u2067\u2068\u2069\u202A-\u202E]/g, '')
    .replace(/R\$/g, '')
    .replace(/\u00A0/g, '')
    .replace(/\s+/g, '')
    .trim();
  // Remover pontos de milhar, trocar vírgula por ponto
  cleaned = cleaned.replace(/\./g, '').replace(',', '.');
  return parseFloat(cleaned) || 0;
}

