function checkIsOpen() {
  // MÉTODO 1: Bloqueio de chips (MAIS CONFIÁVEL)
  const chipWrapper = document.querySelector("[data-role='chip-stack-wrapper']");
  if (chipWrapper) {
    const className = chipWrapper.className || '';
    const isBlocked = className.includes('prevent') || className.includes('blocked');
    if (isBlocked) return false;
    if (!isBlocked) return true;
  }

  // MÉTODO 2: Texto do semáforo
  const textEl = document.querySelector('[class*="trafficLightText"]');
  if (textEl) {
    const text = (textEl.innerText || '').toUpperCase();
    if (text.includes('FAÇAM') || text.includes('PLACE')) return true;
    if (text.includes('NÃO') || text.includes('NO MORE')) return false;
  }

  // MÉTODO 3: Timer visível
  const timer = document.querySelector("[data-role='circle-timer']");
  if (timer) {
    const style = getComputedStyle(timer);
    return style.display !== 'none' && parseFloat(style.opacity) > 0.3;
  }

  return null; // Desconhecido
}

