async function executarAposta(chipValue, betSpotId) {
  // 1. Verificar se aberto
  if (!checkIsOpen()) return { error: 'APOSTAS_FECHADAS' };

  // 2. Selecionar ficha
  const chip = document.querySelector(`[data-role='chip'][data-value='${chipValue}']`);
  if (!chip) return { error: 'CHIP_NOT_FOUND' };
  chip.click();
  await new Promise(r => setTimeout(r, 100));

  // 3. Clicar no spot
  const spot = document.querySelector(`[data-bet-spot-id='${betSpotId}']`);
  if (!spot) return { error: 'SPOT_NOT_FOUND' };

  const event = new PointerEvent('click', {
    bubbles: true, cancelable: true, view: window,
    pressure: 0.5, pointerType: 'mouse'
  });
  spot.dispatchEvent(event);

  return { success: true, chip: chipValue, spot: betSpotId };
}

